import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, color } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3 } = ctx.THREE;

  // Root container
  const root = new Group();

  // ---------- Backdrop gradient plane ----------
  const backdropGeom = new PlaneGeometry(7, 6);
  const uvNode = uv();
  const gradientColor = mix(color('#0b0b10'), color('#e8ecf2'), uvNode.y);
  const backdropMat = new MeshBasicNodeMaterial({ color: gradientColor });
  const backdropMesh = new Mesh(backdropGeom, backdropMat);
  backdropMesh.position.set(0, 0, -2.5);
  root.add(backdropMesh);

  // ---------- Hero image textured plane ----------
  const imageGeom = new PlaneGeometry(4, 2.25); // 16:9 approx
  const imageMat = new MeshBasicNodeMaterial({ map: null, transparent: true });
  const imageMesh = new Mesh(imageGeom, imageMat);
  imageMesh.position.set(0, 0, 0);
  root.add(imageMesh);

  // Load texture asynchronously
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      imageMat.map = tex;
      imageMat.needsUpdate = true;
    });
  }

  // ---------- Text content ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  items.forEach((item) => {
    const txtOpts = {
      fontSize: item.typography?.fontSize ?? 42,
      color: '#e8ecf2',
      align: 'center',
    };
    const txtObj = ctx.fontAtlas.createText(item.text, txtOpts);
    // Position text slightly above the image plane
    txtObj.position.set(0, 1.2, 0.01);
    root.add(txtObj);
  });

  // ---------- Event handlers placeholder ----------
  root.userData.handlers = {};

  // ---------- Cleanup ----------
  const timelines = [];
  root.userData.cleanup = () => {
    // Dispose geometries and materials
    root.traverse((child) => {
      if (child.isMesh) {
        if (child.geometry) child.geometry.dispose();
        if (child.material) child.material.dispose();
      }
    });
    // Kill GSAP timelines
    timelines.forEach((tl) => tl.kill());
    // Primitive cleanups (none in this node)
    // No additional resources
  };

  // Return the assembled node
  return root;
}
